      "indications": "教学范围内用于产 β-内酰胺酶敏感菌所致的中耳炎、鼻窦炎、皮肤软组织感染及部分吸入性肺炎的讨论。",
      "peds_notes": "复方制剂中克拉维酸比例固定，按体重加量时克拉维酸也随之增加，长期大剂量易致腹泻与肝酶异常；建议随餐服用以减轻胃肠道反应，并按规格换算阿莫西林组分。",
      "dose_note": "教学性常用范围以阿莫西林组分计约 25–45 mg/kg/日，分 2–3 次口服，须核对说明书并按本院制剂规格换算，同时对照感染部位指南；不得把成人片剂掰分后给低体重儿童，不能直接照抄为处方。",
      "max_single": "原则性参考：以阿莫西林组分计单次一般不超过 1 g，日总量与疗程须服从说明书与临床评估。",
      "renal_note": "肾功能不全者需按肌酐清除率延长间隔或减少剂量，克拉维酸在透析患者中需额外补充给药。",
      "hepatic_note": "有报告出现胆汁淤积性肝炎与肝酶升高，原有肝病或长期用药者需监测转氨酶并避免重复疗程。",
      "cautions": "腹泻发生率高，需与感染性腹泻鉴别；用药期间出现黄疸、尿色加深应立即评估肝功能。",
      "contraindications": "青霉素类过敏史者禁用；既往使用本品出现胆汁淤积性黄疸或肝功能损害者禁用。",
      "adverse": "腹泻、恶心、皮疹、肝酶升高、念珠菌过度生长，偶见严重过敏反应。",
      "monitoring": "记录排便次数与性状，必要时查肝功能与血常规，观察皮疹与过敏征象。",
      "age_limit": "不同规格说明书对最低适用年龄与剂型限制不同，婴儿使用须逐项核对规格说明。",
      "interactions": "与丙磺舒、别嘌醇、甲氨蝶呤合用需注意浓度与毒性增加；与口服避孕药等无确切临床影响但仍需说明。",
