      "peds_notes": "第一代头孢主要覆盖革兰阳性球菌，对流感嗜血杆菌与肺炎链球菌耐药株覆盖不足；儿童宜选颗粒或混悬液按体重分次给药，空腹或餐后服用依说明书而定，疗程结束需评估是否真正为细菌感染。",
      "dose_note": "教学性常用范围约 25–50 mg/kg/日，分 3–4 次口服，日总量一般不超过 4 g；具体剂量与分次须核对本院制剂说明书，不能直接照抄为处方执行。",
      "max_single": "原则性参考：单次一般不超过 0.5 g，日总量不超过说明书上限，肾功能不全者还需进一步下调。",
      "renal_note": "主要经肾排泄，肾功能不全时需减少日剂量或延长间隔，必要时按肌酐清除率计算。",
