      "peds_notes": "对部分流感嗜血杆菌与卡他莫拉菌有效，常用于中耳炎与鼻窦炎的门诊讨论；儿童按体重分 2–3 次服用，混悬液需按说明配制成所需浓度并冷藏保存，疗程应覆盖足够天数。",
      "dose_note": "教学性常用范围约 20–40 mg/kg/日，分 2–3 次口服，单日总量一般不超过 1 g；具体分次与上限须核对本院说明书与感染部位指南，不能照抄为处方。",
      "max_single": "原则性参考：单次不超过说明书标注上限，日总量不得超过 1 g 类常规范围，超量无额外获益。",
      "renal_note": "肾功能中度至重度受损时需减量或延长间隔，透析患者给药需按说明书补充方案执行。",
      "hepatic_note": "一般无需调整，偶见一过性转氨酶升高，原有肝病者建议监测。",
      "cautions": "有血清病样反应报告，表现为皮疹、关节痛与发热，需与感染本身鉴别；青霉素过敏者慎用。",
      "contraindications": "对头孢菌素类过敏者禁用；既往出现头孢菌素相关严重过敏反应者禁用。",
      "adverse": "腹泻、恶心、皮疹、血清病样反应、嗜酸性粒细胞增多，偶见伪膜性肠炎。",
      "monitoring": "观察皮疹与关节症状，长疗程复查血常规、肾功能，注意腹泻性质改变。",
      "age_limit": "混悬剂说明书通常限定最低月龄，1 月龄以内婴儿使用须逐项核对说明与专科意见。",
      "interactions": "与丙磺舒合用可升高血药浓度；与口服抗凝药合用需留意凝血指标变化。",
