      "peds_notes": "半衰期长、每日一次给药便于门诊与住院使用，脑膜炎需更高日量并延长疗程；不得与含钙输液同瓶或同一管路输注，高胆红素血症与低白蛋白新生儿用药风险需单独评估。",
      "dose_note": "教学性常用范围约 50–80 mg/kg/日，每日 1 次静脉给药，脑膜炎可至 100 mg/kg/日并分次；具体剂量、单次上限与疗程须核对说明书与本院方案，不能照抄为处方。",
      "max_single": "原则性参考：常规感染单次一般不超过 2 g，脑膜炎剂量亦不超过说明书上限，超量增加胆泥与神经毒性风险。",
      "renal_note": "肾功能轻度受损通常无需调整，因兼有肝胆排泄；严重肾衰竭合并肝病时需减量并监测浓度。",
