      "peds_notes": "对革兰阳性球菌与厌氧菌覆盖好、骨组织穿透性佳，常用于化脓性皮肤感染与骨髓炎的口服序贯；口服液口感与胃肠耐受需考虑，尽量足量饮水以减少食管刺激，疗程中警惕艰难梭菌相关性腹泻。",
      "dose_note": "教学性常用范围约 20–40 mg/kg/日，分 3–4 次口服或分 2–3 次静脉给药，重症感染可加量；具体剂量与疗程须核对本院说明书与感染部位指南，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 0.6 g 静脉或 0.45 g 口服，日总量不得超过说明书上限，超量不改善预后。",
