      "indications": "教学范围内用于耐甲氧西林金黄色葡萄球菌（MRSA）等革兰阳性球菌重症感染、中枢感染与导管相关感染的静脉治疗讨论。",
      "peds_notes": "儿童清除率高于成人，常需按体重与肾功能分次给药并以谷浓度或 AUC 指导调整；输注速度过快可致红人综合征，须按说明书延长输注时间；口服剂型不用于全身感染，仅用于艰难梭菌肠炎。",
      "dose_note": "教学性常用范围约 40–60 mg/kg/日，分 3–4 次静脉输注，重症可按负荷量起始；具体剂量须核对说明书并依据血药浓度监测与肾功能，对照本院方案确定，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 1 g（或按体表面积上限），日总量须经浓度监测确认，超量显著增加肾毒性。",
      "renal_note": "主要经肾排泄，肾功能不全时须延长间隔并密切监测浓度与血肌酐，避免与其他肾毒性药物联用。",
      "hepatic_note": "肝功能对清除影响较小，一般无需调整，严重肝病伴腹水者需结合肾功能重新评估。",
      "cautions": "肾毒性与耳毒性，联用哌拉西林他唑巴坦等可增加急性肾损伤风险；输注相关红人综合征需与过敏鉴别。",
