      "contraindications": "对青霉素类或 β-内酰胺酶抑制剂过敏者禁用；既往发生严重速发型过敏反应者禁用。",
      "adverse": "腹泻、皮疹、血小板减少、转氨酶升高、肾功能损害、注射部位静脉炎，偶见严重过敏。",
      "monitoring": "监测皮疹、便次、血常规、肾功能与电解质，联合万古霉素时每日评估肌酐。",
