      "indications": "教学范围内用于厌氧菌感染、贾第虫与阿米巴感染及腹腔、盆腔厌氧菌混合感染的联合治疗讨论。",
      "peds_notes": "对厌氧菌覆盖好，常与第三代头孢或广谱青霉素联用；儿童口服制剂选择有限，可掰分片剂或按说明书使用混悬剂；用药期间及停药后数日避免含酒精制品，口感金属味影响服药依从性。",
      "dose_note": "教学性常用范围约 20–30 mg/kg/日，分 3 次口服或静脉给药，阿米巴与贾第虫疗程按指南延长；具体剂量与疗程须核对本院说明书，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 0.5 g，日总量不超过说明书上限，长疗程需评估神经毒性。",
      "renal_note": "轻中度肾功能不全一般无需调整，重度肾衰或透析患者需减量并考虑透析补充。",
