      "cautions": "长疗程大剂量可引起周围神经病变与共济失调，出现肢端麻木需停药评估；治疗期间避免饮酒及含乙醇制剂。",
      "contraindications": "对硝基咪唑类过敏者禁用；妊娠早期与哺乳期使用须按说明书与专科评估处理。",
      "adverse": "恶心、金属味、腹部不适、口腔念珠菌增多、尿液深色，长疗程致周围神经病变。",
