      "peds_notes": "剂量以甲氧苄啶组分计量更常用，需分 2 次口服并充分饮水；2 月龄以下婴儿一般避免使用，因胆红素竞争白蛋白结合可致核黄疸风险；葡萄糖-6-磷酸脱氢酶缺乏者需评估溶血风险。",
      "dose_note": "教学性常用范围以甲氧苄啶组分计约 6–10 mg/kg/日，分 2 次口服，预防剂量与疗程另按指南分档；具体剂量须核对本院说明书与适应证指南，不能照抄为处方。",
      "max_single": "原则性参考：单次以甲氧苄啶计一般不超过 160 mg，日总量不得超过说明书上限。",
      "renal_note": "肾功能不全时需按肌酐清除率减量，并增加饮水以减少结晶尿风险，定期监测肌酐。",
