      "indications": "教学范围内用于甲型与乙型流感的抗病毒治疗与暴露后预防讨论。",
      "peds_notes": "按体重分档给药，1 岁以下婴儿剂量须核对说明书与指南；起病 48 小时内启动获益最大，但重症或高危患儿即使超过 48 小时仍应评估使用；肾功能受损需调整，服药后呕吐常见，可分次随餐服用。",
      "dose_note": "教学性常用范围约 2 mg/kg/次，每日 2 次，连用 5 日，按体重分档（如 ≤15kg、15–23kg 等）；具体分档与疗程须核对本院说明书与流感指南，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 75 mg，预防与治疗疗程均不超过说明书规定天数。",
      "renal_note": "主要经肾排泄，肾功能不全时需减量或延长间隔，透析患者按说明书单独制定方案。",
      "hepatic_note": "轻中度肝功能异常一般无需调整，严重肝病者用药经验有限，需监测并评估风险。",
      "cautions": "有神经精神事件报告，儿童服药期间需观察异常行为与自伤倾向；呕吐明显者注意补液与误吸。",
      "contraindications": "对奥司他韦过敏者禁用；严重肾功能不全未调整剂量时不宜使用。",
