      "age_limit": "1 岁以下婴儿尤其是早产儿的使用须逐项核对说明书与指南，出生 2 周内婴儿证据有限。",
      "interactions": "与丙磺舒合用可升高血药浓度；与减毒活流感疫苗需错开时间以免影响疫苗效果。",
