      "indications": "教学范围内用于巨细胞病毒（CMV）感染的治疗与免疫功能低下患儿的预防讨论。",
      "peds_notes": "骨髓抑制作用明显，儿童按体重分 2 次静脉给药并在疗程中加密血常规监测；口服制剂生物利用度有限，多用于维持或预防阶段；先天性 CMV 感染的治疗决策须由专科团队综合听力、眼底与神经系统评估后制定。",
      "dose_note": "教学性常用范围约 5 mg/kg/次，每 12 小时静脉给药，维持期按指南减为每日 1 次；具体剂量、疗程与是否联合免疫球蛋白须核对本院说明书与专科方案，不能照抄为处方。",
      "max_single": "原则性参考：单次不超过说明书标注的 5–6 mg/kg 范围，日总量不得突破上限，超量显著加重骨髓抑制。",
      "renal_note": "主要经肾排泄，肾功能不全时必须按肌酐清除率减量，否则中性粒细胞减少风险显著升高。",
      "hepatic_note": "肝功能异常者需监测转氨酶与胆红素，严重肝病时用药风险与获益需重新评估。",
      "cautions": "可致中性粒细胞与血小板减少、生殖毒性，操作与配制需按细胞毒性药物规范防护；输注液碱性强，注意静脉炎。",
      "contraindications": "对更昔洛韦或阿昔洛韦过敏者禁用；严重中性粒细胞与血小板减少未纠正时禁用。",
      "adverse": "中性粒细胞减少、血小板减少、贫血、发热、皮疹、肝酶升高、静脉炎，偶见肾功能损害。",
      "monitoring": "每 2–3 日复查血常规，监测肾功能、肝功能与眼底、听力变化，注意继发感染。",
