      "peds_notes": "口服生物利用度高，可与静脉序贯使用；儿童清除率较成人快，常需按体重给药并分次；早产儿与新生儿半衰期长，需延长间隔，剂量方案必须依据本院新生儿用药资料并评估肝酶变化。",
      "dose_note": "教学性常用范围约 3–12 mg/kg/日，每日 1 次口服或静脉给药，负荷量与疗程按感染部位分档；具体剂量须核对本院说明书与真菌感染指南，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 400 mg，日总量不得超过说明书上限，长疗程需评估累积毒性。",
