      "hepatic_note": "可引起转氨酶升高甚至肝衰竭，原有肝病者需减量并密切监测肝功能与黄疸。",
      "cautions": "可延长 QT 间期并抑制 CYP2C9/CYP3A4，与多种药物联用时须逐一核对相互作用；出现皮疹伴发热需警惕严重皮肤反应。",
      "contraindications": "对三唑类过敏者禁用；与特非那定、西沙必利等明显延长 QT 的药物合用禁用。",
      "adverse": "恶心、腹痛、皮疹、转氨酶升高、QT 延长、血细胞减少，偶见严重皮肤反应与肝损伤。",
      "monitoring": "监测皮疹、肝功能与心电图风险，长疗程复查血常规与肾功能，评估药物相互作用。",
