      "indications": "教学范围内用于川崎病抗炎与抗血小板、特定风湿性疾病及部分抗血小板治疗的讨论。",
      "peds_notes": "儿童病毒感染期使用与瑞氏综合征相关，因此不作为常规退热药；仅在川崎病、特定风湿病或抗血小板等明确适应证下由专科使用，剂量与疗程按病种分层，需与家长说明为何不能用它退热。",
      "dose_note": "教学性常用范围按适应证差异很大（抗血小板为小剂量，川崎病抗炎期需较大剂量并分次），具体剂量与疗程须核对说明书并依据专科指南与本院制剂规格，不能照抄为处方，尤其禁止用于儿童常规退热。",
      "max_single": "原则性参考：不同适应证上限差异显著，均不得超过说明书对应适应证标注的上限，超量致水杨酸中毒。",
      "renal_note": "肾功能不全时清除减慢、易蓄积中毒，需减量并监测水杨酸浓度与肌酐。",
      "hepatic_note": "肝功能不全者慎用，可致转氨酶升高与凝血异常，严重肝病者避免使用。",
      "cautions": "病毒感染（水痘、流感）期间禁用以免诱发瑞氏综合征；有消化道溃疡、出血倾向或哮喘者慎用；术前需按规范停药。",
      "contraindications": "对水杨酸类过敏者禁用；有水痘或流感样症状的儿童、活动性消化道出血者禁用。",
      "adverse": "胃肠刺激与出血、耳鸣、肝功能异常、过敏反应，过量致代谢性酸中毒与中枢症状。",
      "monitoring": "长疗程监测凝血功能、肝功能与水杨酸浓度，观察耳鸣、黑便与出血征象。",
      "age_limit": "不用于儿童与青少年病毒性感染的退热；川崎病等适应证按专科指南在婴儿期亦可使用。",
      "interactions": "与抗凝药、其他非甾体抗炎药合用增加出血风险；与丙磺舒竞争排泄；与甲氨蝶呤合用增加毒性。",
