      "peds_notes": "在新生儿科主要用于有血流动力学意义的动脉导管未闭，须由新生儿专科按日龄、体重与肾功能决定是否用药，并监测尿量与肌酐；年长儿抗炎用途有限，因不良反应较多不作为常规选择。",
      "dose_note": "教学性方案按适应证与体重分档（如新生儿按日龄分次给药，共 3 剂），具体剂量、间隔与是否重复须核对说明书并依据新生儿科方案与本院给药规范，不能照抄为处方。",
      "max_single": "原则性参考：单次不超过说明书标注上限，新生儿总累积剂量须严格限制，超量增加肾与消化道损害。",
      "renal_note": "可减少肾血流，早产儿与肾功能不全者易致少尿与肌酐升高，用药期间必须记录尿量并监测肾功能。",
