      "contraindications": "对吲哚美辛过敏者禁用；活动性消化道溃疡、出血倾向、严重肾功能不全者禁用；坏死性小肠结肠炎患儿禁用。",
      "adverse": "少尿、血肌酐升高、消化道出血、血小板减少、黄疸，偶见颅内出血风险增加。",
      "monitoring": "用药前后监测尿量、肌酐、电解质与血常规，观察消化道出血与导管关闭的超声变化。",
      "age_limit": "早产儿使用须满足特定胎龄与体重条件并由新生儿科评估；年长儿抗炎用途须专科决定。",
      "interactions": "与氨基糖苷类、万古霉素等肾毒性药合用增加肾损害；与抗凝药合用增加出血；与呋塞米合用减弱利尿效果。",
