      "indications": "教学范围内用于哮喘急性喘息发作、运动诱发支气管痉挛及毛细支气管炎试验性治疗的讨论。",
      "peds_notes": "急性喘息首选吸入给药，学龄前儿童配合储雾罐或面罩雾化，按需间断使用而非长期定时给药；吸入后心率增快与手抖常见，若短时间内反复需要提示病情控制不佳需升级评估，口服剂型全身不良反应多已少用。",
      "dose_note": "教学性雾化常用范围约 2.5 mg/次（<5 岁可 2.5 mg 或按 0.15 mg/kg），必要时每 20 分钟 1 次共 3 次，随后按需；具体剂量与频次须核对本院雾化溶液说明书与哮喘指南，不能照抄为处方。",
      "max_single": "原则性参考：雾化单次一般不超过 5 mg，24 小时累积次数须受控，过量致心动过速、低钾与震颤。",
      "renal_note": "肾功能不全一般无需调整，但反复大剂量使用应注意低钾血症，需监测电解质。",
      "hepatic_note": "肝功能异常一般无需调整剂量，重度肝病者口服给药需谨慎评估。",
      "cautions": "可致心动过速、震颤、低钾与高血糖；雾化时注意氧流量与面罩位置，避免眼接触；频繁使用提示需重新评估控制方案。",
      "contraindications": "对沙丁胺醇或制剂成分过敏者禁用；明显快速性心律失常未控制者慎用。",
      "adverse": "手抖、心悸、心动过速、头痛、低钾血症，大剂量时可致乳酸升高与心律失常。",
      "monitoring": "观察呼吸频率、喘鸣改善与心率，重症监测血钾、血气与氧饱和度，评估吸入技术是否正确。",
      "age_limit": "雾化溶液可用于婴幼儿但须核对说明书；气雾剂需配合储雾罐，5 岁以下不建议直接干粉吸入。",
      "interactions": "与非选择性 β 受体阻滞剂合用可拮抗并诱发支气管痉挛；与利尿剂、糖皮质激素合用加重低钾；与茶碱类合用增加心律失常风险。",
