      "peds_notes": "属长期控制药而非急救药，需规律使用并评估吸入技术与依从性；雾化后必须漱口、洗脸以减少口咽念珠菌与皮肤刺激；急性喉炎单次雾化可减轻水肿，但重度呼吸困难仍需肾上腺素与全身激素并评估气道。",
      "dose_note": "教学性雾化常用范围约 0.5–1 mg/次，每日 1–2 次，长期控制剂量按病情分档；具体剂量、疗程与减量方案须核对本院说明书与哮喘指南，不能照抄为处方。",
      "max_single": "原则性参考：雾化单次一般不超过 1 mg，长期日总量须在说明书与指南范围内，避免长期大剂量影响生长速度。",
      "renal_note": "肾脏对吸入激素影响小，一般无需调整剂量，全身吸收极少。",
      "hepatic_note": "主要经肝代谢，严重肝功能不全时全身暴露增加，需评估剂量并监测激素相关不良反应。",
      "cautions": "长期大剂量可能影响身高增长速度，需定期测量并评估获益；不用于急性重度喘息单独抢救；雾化面罩需贴合以减少眼周刺激。",
      "contraindications": "对布地奈德或吸入制剂成分过敏者禁用；活动性呼吸道结核或未控制的真菌感染者慎用。",
      "adverse": "口咽念珠菌、声音嘶哑、咽部刺激、咳嗽，长期大剂量可致生长速度减慢与肾上腺抑制可能。",
      "monitoring": "定期评估身高体重、喘息控制水平与吸入技术，雾化后检查口腔黏膜，必要时查骨密度。",
