      "peds_notes": "口服每日 1 次、依从性好，但抗炎强度弱于吸入激素，仅作为附加或替代选择，不能用于急性发作抢救；用药期间需告知家长观察情绪与睡眠行为改变，出现明显异常应停药并复诊。",
      "dose_note": "教学性按年龄段分档给药（如 6 月龄至 5 岁常用 4 mg、6–14 岁常用 5 mg，每日 1 次晚间口服），具体分档须核对本院说明书与哮喘指南，不能照抄为处方。",
      "max_single": "原则性参考：单日总量按年龄分档且不超过说明书上限，加倍剂量不提高疗效而增加神经精神事件风险。",
      "renal_note": "肾功能不全一般无需调整剂量，透析患者经验有限但无需特殊减量。",
