      "dose_note": "教学性雾化常用范围约 250–500 μg/次，每日 3–4 次或急性期与沙丁胺醇联合每 20 分钟 1 次共 3 次；具体剂量与频次须核对本院说明书与哮喘指南，不能照抄为处方。",
      "max_single": "原则性参考：雾化单次一般不超过 500 μg，日累积剂量须受控，过量加重口干、尿潴留与眼压升高风险。",
