      "peds_notes": "严重过敏反应首选肌内注射大腿前外侧，不因等待静脉通路而延误；同时呼叫急救、平卧抬腿、给氧并补液；急性喉炎雾化给药可减轻黏膜水肿，但不能替代气道评估与全身激素。",
      "dose_note": "教学性肌注常用范围约 0.01 mg/kg（按 1:1000 浓度计），单次一般不超过 0.3–0.5 mg，必要时 5–15 分钟可重复；具体剂量与重复次数须核对本院急救流程与过敏反应指南，不能照抄为处方。",
      "max_single": "原则性参考：单次肌注一般不超过 0.5 mg，重复给药需评估反应；误用静脉途径或剂量错误可致严重心律失常。",
      "renal_note": "肾功能对急救给药影响小，不作为剂量调整依据，抢救优先保证给药时机。",
      "hepatic_note": "肝功能对急救给药影响有限，不作为急救剂量调整依据。",
      "cautions": "必须核对浓度（1:1000 与 1:10000 易混淆）与给药途径；冠心病、心律失常者风险较高，但过敏休克时仍以救命为先。",
      "contraindications": "对肾上腺素过敏者禁用；除危及生命的抢救情形外，未控制的严重心律失常与嗜铬细胞瘤者慎用。",
      "adverse": "心悸、震颤、焦虑、血压升高、心律失常、局部组织缺血，静脉外渗可致皮肤坏死。",
      "monitoring": "抢救中持续监测心率、心律、血压与氧饱和度，观察注射部位与反应，记录给药时间与剂量。",
      "age_limit": "婴幼儿按体重精确计算剂量并核对浓度，自动注射器规格需按体重选择，避免成人规格误用。",
      "interactions": "与非选择性 β 受体阻滞剂合用可能致血压反常升高；与三环类抗抑郁药、可卡因等合用增加心律失常风险；与卤化麻醉药合用增加心律失常。",
