      "indications": "教学范围内用于过敏性鼻炎、慢性荨麻疹及其他组胺介导的瘙痒性皮肤病的对症治疗讨论。",
      "peds_notes": "嗜睡等中枢抑制明显少于第一代抗组胺药，适合需要上学的儿童；按年龄与体重分档，2 岁以下使用须核对说明书；对急性严重过敏反应无效，不能替代肾上腺素，症状持续者应同时排查过敏原。",
      "dose_note": "教学性常用范围按年龄分档（如 2–12 岁体重≤30kg 常用 5mg、>30kg 用 10mg，每日 1 次），具体剂量须核对本院说明书与年龄分档，不能照抄为处方。",
      "max_single": "原则性参考：单日总量不超过说明书标注上限，加倍剂量不增加疗效而增加嗜睡与口干。",
      "renal_note": "重度肾功能不全时需延长给药间隔，透析患者用药需按说明书评估。",
      "hepatic_note": "肝功能不全时清除减慢，建议减量或延长间隔并观察嗜睡等不良反应。",
      "cautions": "少数患儿仍可出现嗜睡或反常兴奋；糖浆含辅料需注意，糖尿病或特殊饮食患儿核对成分；不用于急性喉水肿抢救。",
      "contraindications": "对氯雷他定或制剂成分过敏者禁用；严重肝功能不全未减量时不宜使用。",
      "adverse": "嗜睡、口干、头痛、乏力、食欲增加，偶见心动过速与过敏反应。",
      "monitoring": "评估鼻部与皮肤症状改善及嗜睡程度，长期使用注意体重与学习状态变化。",
      "age_limit": "2 岁以下儿童使用须核对说明书并评估获益，婴幼儿优选按体重精确计量的剂型。",
      "interactions": "与酮康唑、大环内酯类等 CYP3A4 抑制剂合用可升高血药浓度；与中枢抑制药合用加重嗜睡。",
