      "indications": "教学范围内用于过敏性鼻炎、慢性荨麻疹与特应性皮炎瘙痒的对症治疗讨论。",
      "peds_notes": "起效较快、滴剂便于婴幼儿按体重计量，但嗜睡发生率高于部分同类药物，晚间服用可减少白天困倦；肾功能不全需调整，荨麻疹治疗中需评估是否需要联合其他药物与寻找诱因。",
      "dose_note": "教学性常用范围约 0.25 mg/kg/次，每日 1–2 次，或按年龄分档（2–6 岁常用 2.5mg 每日 2 次）；具体剂量须核对本院说明书与年龄分档，不能照抄为处方。",
      "max_single": "原则性参考：单日总量一般不超过 10 mg，肾功能不全者上限更低，超量增加嗜睡与口干。",
      "renal_note": "主要经肾排泄，肾功能不全时须减量并延长间隔，严重肾衰者需按说明书调整。",
