      "cautions": "可致嗜睡，服药后避免骑车与危险活动；少数儿童出现反常兴奋；不用于急性严重过敏反应抢救。",
      "contraindications": "对西替利嗪或羟嗪类过敏者禁用；严重肾功能不全未减量者不宜使用。",
