      "indications": "教学范围内用于痰液黏稠、排痰困难的支气管炎与肺炎的辅助化痰治疗讨论。",
      "peds_notes": "祛痰药只是辅助，不能替代补液、雾化、拍背与病因治疗；婴幼儿气道狭窄、咳嗽力量弱，用药后痰液变稀但排痰能力不足时可能加重气道阻塞，需配合体位引流并观察呼吸。",
      "dose_note": "教学性常用范围约 1.2–1.6 mg/kg/日，分 2–3 次口服，雾化与静脉剂量另按说明书分档；具体剂量与疗程须核对本院制剂说明书，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 30 mg，日总量不超过说明书上限，过量可致恶心与唾液增多。",
      "renal_note": "重度肾功能不全时其代谢物蓄积，需减量或延长给药间隔。",
      "hepatic_note": "严重肝功能不全时需减量，因代谢清除能力下降可能增加不良反应。",
      "cautions": "不主张与强力镇咳药同时使用，以免痰液潴留；出现皮疹或黏膜损伤需停药；雾化时避免与其他药物混合配伍。",
      "contraindications": "对氨溴索或溴己新类过敏者禁用；妊娠早期按说明书限制使用。",
      "adverse": "恶心、胃部不适、口干、皮疹，偶见严重皮肤黏膜反应与过敏。",
      "monitoring": "观察痰液性状、咳嗽效率与呼吸状态，注意皮疹，评估是否仍需继续用药。",
      "age_limit": "不同剂型说明书对婴儿最低年龄限制不同，新生儿与早产儿使用须严格核对并评估必要性。",
      "interactions": "与镇咳药合用可能致痰液潴留；与抗生素（如阿莫西林、头孢类）合用可提高后者在肺组织的浓度。",
