      "peds_notes": "属吸附剂，只能作为口服补液的辅助，不能替代补液；需与其他口服药间隔 1–2 小时服用以免吸附影响吸收；腹泻治疗核心仍是评估脱水程度与补液，血便、高热或精神差需就医而非单纯止泻。",
      "dose_note": "教学性常用范围按年龄分档（如 1 岁以下每日 1 袋、1–2 岁每日 1–2 袋、2 岁以上每日 2–3 袋，分次冲服），具体分档须核对本院说明书与腹泻诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 1 袋（3g），日总量按年龄分档且不超过说明书上限，过量可致便秘。",
