      "indications": "教学范围内用于急性腹泻轻中度脱水与预防脱水的口服补液治疗讨论。",
      "peds_notes": "腹泻治疗的核心措施，采用少量多次频服，呕吐不是禁忌而是应放慢速度继续补；配液必须严格按说明水量，过浓或过稀均可致电解质紊乱；重度脱水、意识改变或无法口服者需静脉补液而非口服。",
      "dose_note": "教学性常用原则为每次稀便后按体重补充（如 <6 月龄 50ml、6 月龄–2 岁 50–100ml、2–10 岁 100–150ml），具体量与配液浓度须核对本院制剂说明书与腹泻诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次补液量按体重与脱水程度计算，短时间大量灌服易致呕吐，应分次少量给予。",
      "renal_note": "肾功能不全或尿量明显减少时补钾补钠需谨慎，须评估电解质与尿量后决定配方与速度。",
      "hepatic_note": "肝功能不全本身不限制使用，但合并腹水与低钠血症者需评估钠负荷。",
      "cautions": "必须使用洁净饮用水配制并现配现用；不可用牛奶、果汁或含糖饮料冲配；休克、肠梗阻与频繁呕吐无法口服者需改静脉补液。",
      "contraindications": "少尿或无尿、严重脱水休克、肠梗阻及葡萄糖吸收不良者禁用或改用静脉补液。",
      "adverse": "过量过快服用可致呕吐、腹胀，配液错误可致高钠或低钠血症。",
      "monitoring": "监测体重、尿量、精神状态、眼泪与口腔黏膜湿润度，必要时复查电解质。",
      "age_limit": "新生儿与早产儿脱水补液须由新生儿科单独评估，配方与补液速度需另行制定。",
      "interactions": "与高钠或高钾补充剂叠加使用时需核对总入量；与吸附剂同服会影响吸收，应错开时间。",
