      "dose_note": "教学性补钾常用范围约 1–3 mmol/kg/日，稀释后匀速静脉滴注，外周浓度一般不超过 0.3%–0.5%；具体浓度、速度与总量须核对说明书并依据血钾、尿量与本院规范，不能照抄为处方。",
      "max_single": "原则性参考：外周静脉单次补钾速度一般不超过 0.3–0.5 mmol/kg/小时，更高速度仅限重症监护条件下并持续心电监测。",
      "renal_note": "肾功能不全与少尿时易致高钾血症，必须在尿量充足与血钾监测下减量补充，必要时先处理肾衰。",
      "hepatic_note": "肝功能对钾代谢影响有限，但合并腹水使用保钾利尿剂时需警惕高钾。",
