      "contraindications": "高钾血症、无尿或严重肾功能不全未纠正、未经治疗的肾上腺皮质功能减退者禁用静脉补钾。",
      "adverse": "高钾血症致心律失常，外渗致组织坏死，胃肠刺激与恶心（口服），输液部位疼痛。",
