      "peds_notes": "不常规用于心跳骤停或普通腹泻所致轻度酸中毒，仅在明确适应证与血气指导下使用；新生儿与婴儿对碱负荷耐受差，易致颅内出血与电解质紊乱，须严格掌握指征与给药速度。",
      "dose_note": "教学性常用范围按碱缺失计算（约 1–2 mmol/kg 缓慢静脉给予后复查血气），具体剂量须核对说明书并依据血气与本院方案计算，不能照抄为处方或按经验反复给药。",
      "max_single": "原则性参考：单次剂量按碱缺失与体重计算且需复查血气后再决定是否追加，过量致代谢性碱中毒与低钾。",
      "renal_note": "肾功能不全时排碱能力下降，易致代谢性碱中毒与钠负荷过多，需减量并监测血气与电解质。",
