      "contraindications": "代谢性碱中毒、低钙血症未纠正、高钠血症及明显容量负荷过重者禁用或慎用。",
      "adverse": "代谢性碱中毒、低钾血症、低钙性抽搐、高钠血症、外渗性组织损伤与颅内出血风险（新生儿）。",
