      "peds_notes": "静脉给药必须缓慢并持续监测心率，因快速推注可致心动过缓与心律失常；氯化钙刺激性更强，儿科多用葡萄糖酸钙；新生儿低钙常见于早产与糖尿病母亲婴儿，需结合血钙与血糖评估。",
      "dose_note": "教学性常用范围约 10% 溶液 0.5–1 ml/kg（按元素钙计约 10–20 mg/kg）缓慢静注或稀释后滴注，口服补充按元素钙需求分次；具体剂量与速度须核对本院说明书与血症程度，不能照抄为处方。",
      "max_single": "原则性参考：单次元素钙一般不超过 20 mg/kg，推注时间不少于 10 分钟，过量致高钙血症与心律失常。",
      "renal_note": "肾功能不全时钙排泄下降，易致高钙血症与转移性钙化，需减量并监测血钙与尿钙。",
      "hepatic_note": "肝功能对钙代谢影响有限，但低蛋白血症时总钙测定偏低需校正并测离子钙。",
      "cautions": "不可与头孢曲松、碳酸氢钠等配伍；外渗可致严重组织坏死与钙化，须确保通路通畅并观察穿刺部位。",
      "contraindications": "高钙血症、洋地黄中毒、心室颤动及明显高钙尿症者禁用静脉补钙。",
      "adverse": "心动过缓、心律失常、注射部位疼痛与外渗坏死，高钙血症致便秘、多尿与意识改变。",
      "monitoring": "静注时持续心电监测，复查血钙、离子钙、白蛋白与心电图 QT 间期，观察外渗征象。",
      "age_limit": "新生儿与早产儿补钙须按体重精确计量并稀释，静注速度更慢且需心电监测。",
      "interactions": "与头孢曲松、碳酸氢钠、磷酸盐配伍禁忌；与洋地黄类合用增加洋地黄毒性风险；与噻嗪类利尿剂合用增加高钙风险。",
