      "peds_notes": "惊厥急救一线用药，可静脉缓慢推注或无静脉通路时直肠给药；给药同时必须准备吸氧与气道管理，因呼吸抑制与误吸风险明确；推注速度须慢并观察呼吸与血氧，止惊后需查血糖、电解质、体温与病因。",
      "dose_note": "教学性常用范围约 0.2–0.5 mg/kg 静脉缓慢推注或直肠给药，必要时可重复 1 次；具体剂量、给药途径与重复次数须核对本院急救流程与惊厥指南，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 10 mg，重复给药须间隔数分钟并评估呼吸，累积过量致呼吸抑制与意识抑制。",
      "renal_note": "肾功能不全时其代谢物可能蓄积，需延长给药间隔并观察镇静过度。",
      "hepatic_note": "肝功能不全时清除显著减慢，需减量并延长间隔，重症肝病者慎用。",
