      "indications": "教学范围内用于无静脉通路时的惊厥急救、程序性镇静及重症监护镇静的讨论。",
      "peds_notes": "无静脉通路时可肌注或颊黏膜给药，起效较快，适合院前与急诊首剂处理；镇静与呼吸抑制风险明确，给药后须持续监测血氧并备好气道支持，反复给药易蓄积致苏醒延迟。",
      "dose_note": "教学性惊厥急救常用范围约 0.1–0.2 mg/kg 肌注或颊黏膜给药，静脉镇静剂量按操作与监护条件分层；具体剂量、途径与重复次数须核对本院急救流程与镇静规范，不能照抄为处方。",
      "max_single": "原则性参考：单次急救剂量一般不超过 10 mg，重复给药需间隔并评估呼吸与意识，累积剂量过高致呼吸抑制。",
      "renal_note": "肾功能不全时活性代谢物可蓄积，需延长观察时间并减少追加剂量。",
      "hepatic_note": "肝功能不全时清除减慢，镇静时间延长，需减量并延长监测时间。",
      "cautions": "呼吸抑制、低血压与 Paradox 反应（反常兴奋）；与阿片类合用显著增加呼吸抑制；注射后需禁食观察按规范执行。",
      "contraindications": "对苯二氮䓬类过敏者禁用；未具备气道管理与监护条件时不得用于程序性镇静。",
      "adverse": "呼吸抑制、低血压、嗜睡、呃逆、注射部位疼痛，儿童可见反常兴奋与躁动。",
      "monitoring": "给药期间连续监测血氧、呼吸与心率，镇静后按规范评估意识恢复与离院标准。",
      "age_limit": "新生儿与早产儿清除能力低、呼吸抑制风险高，须由具备复苏条件团队按校正年龄减量使用。",
      "interactions": "与阿片类、丙泊酚、巴比妥类合用加重呼吸循环抑制；与 CYP3A4 抑制剂（大环内酯类、唑类）合用延长镇静。",
