      "peds_notes": "新生儿惊厥常用，负荷给药后需监测呼吸与意识，必要时机械通气支持；长期使用对认知行为可能有影响，且为强肝酶诱导剂，联合用药时必须核对相互作用；停药需逐渐减量避免反跳发作。",
      "dose_note": "教学性负荷量约 15–20 mg/kg 静脉缓慢给予，维持量约 3–5 mg/kg/日分次；具体剂量、速度与血药浓度目标须核对本院新生儿与癫痫方案，不能照抄为处方。",
      "max_single": "原则性参考：单次负荷一般不超过 20 mg/kg，超过须分次并监测呼吸与血药浓度，累积过量致深度昏迷。",
      "renal_note": "肾功能不全时排泄减慢，需减量并监测血药浓度与意识状态。",
      "hepatic_note": "主要经肝代谢，严重肝病者需减量；同时其酶诱导作用可影响多种药物代谢。",
