      "peds_notes": "药物相互作用少、无需常规监测血药浓度，适合联合用药；起始后需逐步加量以减少嗜睡与行为改变，家长应观察易激惹、攻击性与情绪波动；肾功能不全需按肌酐清除率调整，停药应逐渐减量。",
      "dose_note": "教学性起始范围约 10–20 mg/kg/日分 2 次口服，按疗效逐步加量至 30–60 mg/kg/日；具体起始量、加量速度与最大日量须核对本院说明书与癫痫指南，不能照抄为处方。",
      "max_single": "原则性参考：日总量一般不超过说明书标注上限（儿童常不超过 60 mg/kg/日或 3 g），加量须分阶段进行。",
      "renal_note": "主要经肾排泄，肾功能不全时须按肌酐清除率减量，透析患者需补充给药。",
