      "peds_notes": "儿童颅高压的降颅压选择需结合病因与循环状态，急性期使用存在争议，须按本院神经科方案并优先保证气道、血压与氧合；输注前后监测渗透压、电解质与尿量，心肾功能不全者易致容量负荷与肺水肿。",
      "dose_note": "教学性常用范围约 0.25–1 g/kg 于 15–30 分钟内静脉输注，必要时按病情重复；具体剂量、间隔与疗程须核对本院说明书与颅高压处理方案，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 1 g/kg，重复给药需监测血浆渗透压与肾功能，累积过量致高渗性脱水与肾损害。",
      "renal_note": "肾功能不全时排泄减慢、易致容量超负荷与渗透性肾病，须减量并密切监测尿量与肌酐。",
      "hepatic_note": "肝功能本身不限制使用，但严重肝病伴低蛋白血症与水钠潴留时需评估容量负荷。",
      "cautions": "输注过快可致一过性血容量增加与心衰、肺水肿；低温结晶需温水复溶后使用；外渗可致组织损伤。",
      "contraindications": "无尿、严重心力衰竭、肺水肿及明显高渗性脱水未纠正者禁用。",
