      "monitoring": "监测意识、瞳孔、血压、尿量、血浆渗透压与电解质，观察呼吸与肺部体征，必要时复查头颅影像。",
      "age_limit": "新生儿与婴儿血容量小、渗透压调节能力弱，使用须由专科评估并精确计算剂量与速度。",
