      "peds_notes": "必须使用输液泵按体重以 μg/kg/min 计算并单独通路输注，避免与碱性药物同通路；儿童升压主要依赖其 α 效应，小剂量改善肾血流的说法证据不足已不再推荐；外周输注需密切观察外渗与灌注。",
      "dose_note": "教学性常用范围约 2–20 μg/kg/min 静脉泵入，按血压与灌注滴定；具体起始剂量、滴定速度与上限须核对本院休克复苏流程与说明书，不能照抄为处方。",
      "max_single": "原则性参考：一般不超过 20 μg/kg/min，超过该范围应考虑换用其他血管活性药，剂量过高增加心律失常与肢端缺血风险。",
      "renal_note": "本身不改善肾灌注，休克伴少尿时应通过恢复循环与液体复苏纠正，而非依赖低剂量多巴胺。",
