      "peds_notes": "婴幼儿血管瘤治疗需由专科评估并在起始阶段监测血糖、心率与血压，小婴儿尤其易发生低血糖，喂奶后给药并避免长时间禁食；哮喘与支气管痉挛史者禁用，剂量调整需逐步进行。",
      "dose_note": "教学性常用范围约 0.5–3 mg/kg/日，分 2–3 次口服，按适应证与耐受逐步加量；具体起始量、加量与疗程须核对本院说明书与专科方案，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过说明书标注上限，日总量不得超过按体重计算的上限，过量致严重心动过缓与低血压。",
      "renal_note": "肾功能不全时清除减慢，需减量并监测心率与血压。",
      "hepatic_note": "主要经肝代谢，肝功能不全时显著减量，严重肝病者慎用。",
      "cautions": "可致心动过缓、低血压、低血糖与支气管痉挛；婴幼儿用药期间需规律喂养，避免空腹；不可突然停药以免反跳性心动过速。",
      "contraindications": "支气管哮喘、重度心动过缓或房室传导阻滞、心源性休克及失代偿性心衰者禁用。",
      "adverse": "心动过缓、低血压、低血糖、嗜睡、支气管痉挛、胃肠不适，婴幼儿可见睡眠与喂养改变。",
      "monitoring": "起始与加量时监测心率、血压与血糖，评估喂养与睡眠，血管瘤者定期评估瘤体大小与皮肤改变。",
