      "peds_notes": "必须在具备新生儿监护与气道管理条件的 NICU 使用，持续泵入并密切监测呼吸与血压；用药后可出现呼吸暂停需备好复苏与插管条件，转诊过程不应中断给药，剂量滴定以氧合与灌注为目标。",
      "dose_note": "教学性常用范围约 0.01–0.05 μg/kg/min 持续静脉泵入并滴定，个别情况需更低起始以避免呼吸暂停；具体起始速度、维持量与调整须核对说明书并依据本院 NICU 流程，不能照抄为处方。",
      "max_single": "原则性参考：输注速度上限须按灌注与氧合反应滴定且不超过说明书标注范围，过量致呼吸暂停、低血压与发热。",
      "renal_note": "肾功能不全者清除可能减慢，需从低剂量起始并密切监测血压与呼吸。",
