      "cautions": "呼吸暂停（尤其低体重早产儿）、低血压、发热与皮肤潮红；长时间使用可致导管组织脆性增加影响手术；必须持续心电与呼吸监测。",
      "contraindications": "对前列腺素类过敏者禁用；呼吸窘迫综合征伴明显呼吸功能不全未支持通气者慎用。",
      "adverse": "呼吸暂停、低血压、发热、皮肤潮红、心动过缓、抽搐（罕见），长期使用致导管壁增厚。",
      "monitoring": "持续监测呼吸、心率、血压、血氧与灌注，观察导管开放的超声征象与尿量，记录泵入速度与调整过程。",
      "age_limit": "主要用于新生儿与小婴儿，剂量须按体重精确计算并具备复苏条件，早产儿更易发生呼吸暂停。",
      "interactions": "与其他血管扩张剂或降压药合用加重低血压；与抗凝药合用时注意出血风险评估。",
