      "indications": "教学范围内用于 1 型糖尿病、糖尿病酮症酸中毒（DKA）与高血糖危象的血糖控制讨论。",
      "peds_notes": "必须核对浓度与注射器具（U-100 与 U-40 不可混用），儿童剂量需精确到 0.5 U 或更低规格；DKA 处理先补液纠正容量不足后以小剂量胰岛素持续泵入，血糖下降速度需受控以免脑水肿；注射部位需轮换。",
      "dose_note": "教学性 DKA 常用范围约 0.05–0.1 U/kg/小时 持续静脉泵入，日常方案按体重与餐食计算基础与餐时剂量；具体剂量、配制浓度与调整速度须核对本院糖尿病与 DKA 流程，不能照抄为处方。",
      "max_single": "原则性参考：单次皮下注射剂量按个体化方案计算，DKA 泵入不得骤然加量，过量致严重低血糖与脑损伤。",
      "renal_note": "肾功能不全时胰岛素清除减慢、低血糖风险增加，需减少剂量并加密血糖监测。",
      "hepatic_note": "严重肝病时糖异生受损，低血糖风险增加，需下调剂量并监测血糖。",
      "cautions": "低血糖为最危险不良反应，需教会家长识别与处理；注射部位脂肪增生或萎缩影响吸收；胰岛素为高警示药品，配制与核对需双人执行。",
      "contraindications": "低血糖发作时禁用；对制剂成分过敏者禁用相应制剂。",
      "adverse": "低血糖、注射部位反应与脂肪营养不良、体重增加、低钾血症（DKA 治疗中）、过敏反应。",
      "monitoring": "监测血糖谱、糖化血红蛋白、血酮与电解质（尤其血钾），DKA 期间每小时评估血糖与神经系统状态。",
      "age_limit": "婴幼儿对低血糖耐受差，剂量需按体重精细调整并保证进食，新生儿高血糖用药须由新生儿科制定方案。",
      "interactions": "与 β 受体阻滞剂合用掩盖低血糖症状；与糖皮质激素、噻嗪类合用升高血糖需求；与口服降糖药合用增加低血糖风险。",
