      "indications": "教学范围内用于先天性甲状腺功能减退症、获得性甲减及甲状腺癌术后抑制治疗的讨论。",
      "peds_notes": "先天性甲减应在诊断后尽早开始治疗以保护神经发育，剂量按体重与年龄分档并随生长调整；需空腹服用并与钙、铁、豆制品间隔至少 4 小时；治疗目标为 TSH 与 FT4 达标，不可自行停药或换用其他制剂。",
      "dose_note": "教学性起始范围约 10–15 μg/kg/日（新生儿与婴儿需较高剂量），年长儿按体重递减，依据 TSH 与 FT4 调整；具体剂量与复查间隔须核对本院说明书与内分泌指南，不能照抄为处方。",
      "max_single": "原则性参考：日总量按年龄与体重分档且不超过说明书上限，过量致医源性甲亢与骨代谢异常。",
      "renal_note": "肾功能对甲状腺素清除影响有限，一般无需调整剂量，合并肾病者仍需按 TSH 评估。",
      "hepatic_note": "严重肝病可能影响转运蛋白与代谢，需加密监测 TSH 与 FT4 调整剂量。",
      "cautions": "过量可致心动过速、易激惹、体重下降与骨密度下降；漏服不应加倍补服；不同制剂之间的生物等效性可能存在差异，换用制剂后需复查。",
      "contraindications": "未治疗的甲状腺毒症、未纠正的肾上腺皮质功能不全及急性心肌梗死期禁用或暂缓。",
      "adverse": "过量时出现心动过速、心悸、震颤、失眠、多汗、体重下降与骨密度降低。",
      "monitoring": "定期复查 TSH、FT4、身高体重与发育评估，婴儿需同时评估骨龄与心功能。",
      "age_limit": "新生儿筛查阳性者应尽快开始治疗，剂量按日龄与体重制定并每 2–4 周复查，早产儿需单独评估。",
      "interactions": "钙剂、铁剂、铝镁抗酸剂、豆制品与膳食纤维降低吸收需错开 4 小时；与华法林合用增强抗凝；苯巴比妥等诱导剂加速代谢。",
