      "indications": "教学范围内用于肾上腺危象抢救、先天性肾上腺皮质增生症替代治疗及严重过敏反应的辅助治疗讨论。",
      "peds_notes": "肾上腺危象时应立即静脉给予并同时补液补糖，不能因等待检查结果而延误；长期替代治疗需按体表面积与生长情况调整，应激状态（发热、手术、呕吐）需临时加量并教育家长掌握应激剂量原则。",
      "dose_note": "教学性危象抢救范围约 50–100 mg/m² 静脉给予后按方案维持，替代治疗约 10–15 mg/m²/日分 3 次口服；具体剂量与应激加量方案须核对本院内分泌方案与说明书，不能照抄为处方。",
      "max_single": "原则性参考：单次抢救剂量按体表面积计算且不超过说明书上限，长期替代不可随意超量以免抑制生长。",
      "renal_note": "肾功能不全者需监测水钠潴留与血压，长期使用注意容量负荷与低钾。",
      "hepatic_note": "肝功能不全时其活化转化受影响，严重肝病者需调整剂量并监测血糖与电解质。",
      "cautions": "长期使用致生长抑制、骨质疏松、高血糖、高血压与感染风险增加；突然停药可诱发肾上腺危象，须逐步减量；水痘与结核暴露者风险高。",
      "contraindications": "全身性真菌感染未控制者禁用；对制剂成分过敏者禁用；活动性未治疗的结核慎用。",
      "adverse": "高血糖、高血压、水钠潴留、低钾、感染风险增加、生长抑制、行为情绪改变与消化道溃疡。",
      "monitoring": "监测血糖、血压、电解质、身高体重与感染征象，长期替代者评估骨龄与肾上腺轴功能。",
      "age_limit": "新生儿与婴儿替代剂量按体表面积精确计算并随生长调整，早产儿需按校正年龄评估。",
      "interactions": "与肝酶诱导剂合用降低疗效；与非甾体抗炎药合用增加消化道出血；与利尿剂合用加重低钾；与疫苗（活疫苗）合用需评估。",
