      "indications": "教学范围内用于重症哮喘、严重过敏性疾病、某些自身免疫与炎症性疾病的短程激素治疗讨论。",
      "peds_notes": "短程治疗（数日）通常无需逐渐减量，但长期或反复使用必须按方案减停；治疗前评估感染灶、血糖与水痘结核暴露史，冲击治疗仅限专科并在监护条件下进行，需监测血压血糖与心律。",
      "dose_note": "教学性常用范围约 1–2 mg/kg/日分次静脉或口服，冲击治疗按专科方案（如 10–30 mg/kg/日，连用数日）；具体剂量、疗程与减量方案须核对本院说明书与专科指南，不能照抄为处方。",
      "max_single": "原则性参考：单次冲击剂量按专科方案且不超过说明书上限，累积剂量越大不良反应风险越高。",
      "renal_note": "肾功能不全一般无需调整，但需监测水钠潴留与血压变化。",
      "hepatic_note": "肝功能不全时清除可能减慢，需减量并监测血糖与电解质。",
      "cautions": "可致高血糖、高血压、感染扩散、消化道出血与情绪行为改变；冲击治疗有罕见严重心律失常报告，需心电监护；不用于普通病毒性上呼吸道感染。",
      "contraindications": "全身性真菌感染未控制者禁用；对制剂成分过敏者禁用；活动性消化道溃疡出血期慎用。",
      "adverse": "高血糖、血压升高、感染风险增加、消化道溃疡、失眠与情绪改变、低钾血症、生长抑制（长期）。",
      "monitoring": "监测血糖、血压、电解质与感染征象，冲击治疗期间心电监护，长期使用评估生长与骨密度。",
      "age_limit": "婴幼儿使用需严格掌握指征，长期用药影响生长，早产儿支气管肺发育不良的激素使用须按新生儿指南评估。",
      "interactions": "与非甾体抗炎药合用增加消化道出血；与肝酶诱导剂合用降低疗效；与利尿剂合用加重低钾；与活疫苗接种需间隔评估。",
