      "peds_notes": "急性喉炎单次口服或肌注即可显著减轻黏膜水肿，通常无需重复；抗炎效价强、盐皮质激素作用弱，长期使用对生长抑制明显，须严格限制疗程；给药前评估感染与水痘暴露史。",
