      "max_single": "原则性参考：单次一般不超过 10 mg，日总量按适应证限制，长期使用需按最小有效剂量并逐步减量。",
      "renal_note": "肾功能不全一般无需调整剂量，但需注意水钠潴留与血压变化。",
