      "max_single": "原则性参考：单次元素铁一般不超过 60 mg，日总量不超过说明书上限，过量铁剂对儿童具毒性需安全存放。",
      "renal_note": "肾功能不全时铁剂代谢受影响较小，一般无需调整，但需监测铁蛋白与血红蛋白反应。",
      "hepatic_note": "肝功能不全者慎用，铁负荷增加可能加重肝损伤，需监测铁蛋白与肝功能。",
