      "peds_notes": "所有新生儿出生后应按本院统一方案肌注维生素 K1 以预防出血症，早产儿剂量与足月儿不同；肌注优于口服的依从性，口服方案需多次补服；怀疑颅内出血时立即给药并做影像评估。",
