      "cautions": "静脉给药须缓慢稀释，曾有严重过敏样反应报告，首选肌注或皮下；注射部位可能出现硬结；黄疸新生儿需评估胆红素。",
      "contraindications": "对维生素 K1 或制剂成分过敏者禁用；严重肝病伴凝血因子缺乏者单用无效需综合处理。",
