      "peds_notes": "正常饮食儿童一般无需常规大剂量补充，仅在有明确缺乏或特殊营养需求时使用；大剂量口服可致腹泻与腹胀，静脉大剂量使用缺乏儿童证据且可能增加草酸盐负荷，不主张作为常规治疗手段。",
      "dose_note": "教学性治疗缺乏常用范围约 100–300 mg/日分次口服，严重缺乏时按医嘱加量；具体剂量与疗程须核对本院说明书与营养指南，不能照抄为处方。",
      "max_single": "原则性参考：单日总量一般不超过 2 g，长期大剂量不推荐，过量致胃肠不适与尿草酸升高。",
      "renal_note": "肾功能不全与草酸盐结石风险者应避免大剂量使用，需评估尿草酸与肾功能。",
      "hepatic_note": "肝功能不全一般无需调整剂量，严重肝病者需评估营养状态整体补充方案。",
      "cautions": "泡腾片含钠量较高，心肾功能不全与限钠患儿应核对成分；大剂量静脉使用可致溶血（G6PD 缺乏者风险）；避免与碱性药物同通路。",
      "contraindications": "对本品过敏者禁用；G6PD 严重缺乏者避免大剂量静脉使用；草酸盐结石患者慎用。",
