      "peds_notes": "仅限局部外用，涂于患处薄薄一层，疗程一般不超过 7–10 日以减少耐药；鼻内去定植需按规范疗程执行并评估是否需要联合全身治疗；避免大面积长期使用与接触眼睛，婴幼儿尿布区使用需注意封包与刺激。",
