      "cautions": "可致心动过速、喂养不耐受、腹胀与烦躁；与多沙普仑等呼吸兴奋剂合用风险叠加；早产儿用药需持续呼吸与心率监测。",
      "contraindications": "对咖啡因或甲基黄嘌呤类过敏者禁用；明显快速性心律失常者禁用。",
      "adverse": "心动过速、烦躁、喂养不耐受、腹胀、尿量增多，极少数致惊厥。",
      "monitoring": "监测呼吸暂停次数与心率、喂养耐受与体重增长，必要时评估血药浓度与电解质。",
      "age_limit": "仅用于早产儿（通常出生体重与胎龄达到特定条件），足月新生儿呼吸暂停的病因需另行评估。",
      "interactions": "与茶碱类、多沙普仑合用增强中枢兴奋；与部分经 CYP1A2 代谢的药物合用可能相互影响浓度。",
