      "indications": "教学范围内用于新生儿与婴儿革兰阴性菌感染（如败血症、尿路感染）的联合抗菌治疗讨论。",
      "peds_notes": "新生儿清除率与日龄、体重相关，给药间隔须按日龄分档并依据血药浓度监测调整；耳毒性与肾毒性风险明确，疗程中须监测峰谷浓度、血肌酐与听力筛查；避免与其他耳肾毒性药物联用，不用于需覆盖厌氧菌的混合感染单药治疗。",
      "dose_note": "教学性常用范围约 4–5 mg/kg/日，每日 1 次或分次给药，具体间隔按日龄与浓度结果调整；具体剂量与监测方案须核对本院新生儿抗感染方案与说明书，不能照抄为处方。",
      "max_single": "原则性参考：单次剂量按体重计算且不超过说明书上限，累积剂量与疗程须受控，超量显著增加耳肾毒性。",
      "renal_note": "主要经肾排泄，肾功能不全时半衰期延长须减量或延长间隔，透析患者按说明书补充给药。",
      "hepatic_note": "肝脏代谢参与少，肝功能不全一般无需调整，但严重肝病合并肾功能受损时需联合评估。",
      "cautions": "耳毒性（可致不可逆听力损害）与肾毒性；神经肌肉阻滞（罕见）；静脉输注须缓慢，避免与 β-内酰胺类同容器混合。",
      "contraindications": "对氨基糖苷类过敏者禁用；重症肌无力与既往氨基糖苷类耳毒性史者禁用或避免使用。",
      "adverse": "耳毒性、肾毒性、皮疹、注射部位反应，罕见神经肌肉阻滞与过敏反应。",
      "monitoring": "监测血药峰谷浓度、血肌酐与尿量，疗程前后做听力筛查，记录尿量与体重变化。",
      "age_limit": "新生儿与早产儿必须按日龄与校正胎龄延长间隔并加密浓度监测，早产儿数据有限需专科评估。",
      "interactions": "与万古霉素、两性霉素 B、强效利尿剂、其他氨基糖苷类合用加重耳肾毒性；与神经肌肉阻滞剂合用增加阻滞风险。",
