      "peds_notes": "仅对阿片类引起的呼吸抑制有效，非阿片类所致呼吸抑制无作用；给药后必须同时给予通气支持，因纳洛酮作用时间短可能再次出现抑制需观察并必要时重复；母亲阿片依赖的新生儿使用可诱发急性戒断与惊厥，须谨慎评估。",
      "dose_note": "教学性常用范围约 0.01–0.1 mg/kg 静脉、肌注或气管内给药，按呼吸抑制程度与说明书分档；具体剂量、途径与重复次数须核对本院急救与新生儿复苏流程，不能照抄为处方。",
      "max_single": "原则性参考：单次一般不超过 2 mg（儿童），新生儿用低浓度规格以避免过量诱发戒断，重复给药需重新评估呼吸。",
      "renal_note": "肾功能不全一般无需调整剂量，急救情形下以恢复通气为优先。",
      "hepatic_note": "严重肝病者代谢可能减慢，但急救时不作为延迟给药的理由，需继续观察呼吸。",
