      "monitoring": "持续监测呼吸频率、血氧、意识与心率，观察至少数小时以防再次抑制，记录给药时间与剂量。",
      "age_limit": "新生儿使用须选低浓度规格并按体重精确计量，早产儿需在复苏条件下给药并观察呼吸。",
      "interactions": "与阿片类镇痛药作用相互拮抗，术后镇痛患者使用时需评估疼痛与戒断；与部分依赖阿片机制的药物合用需重新评估疗效。",
