      "peds_notes": "仅在摄入时间较短（一般 1 小时内）且毒物可被吸附时考虑，意识障碍或吞咽功能受损者在给药前必须先保护气道以防误吸；不被吸附的毒物（强酸强碱、铁剂、锂剂、醇类）无效；给药须按本院中毒处理流程并与毒物咨询中心沟通。",
      "dose_note": "教学性常用范围约 1 g/kg 配制成混悬液口服或经胃管给予（儿童常用 10–25 g 量级），具体剂量与是否重复须核对说明书并依据毒物种类与本院中毒处理方案，不能照抄为处方。",
      "max_single": "原则性参考：单次按 1 g/kg 计算且不超过说明书标注上限，重复给药需评估肠鸣音与排便以防肠梗阻。",
      "renal_note": "不吸收入血，肾功能不全一般无需调整，但需评估毒物本身的肾毒性。",
      "hepatic_note": "肝功能不全一般无需调整剂量，但需评估毒物肝毒性与解毒能力。",
      "cautions": "误吸可致严重吸入性肺炎，意识不清者禁用或先插管；可致便秘与肠梗阻；与解毒剂（如乙酰半胱氨酸）同用时需间隔。",
      "contraindications": "意识障碍未保护气道、肠梗阻、腐蚀性物质与碳氢化合物摄入者禁用。",
      "adverse": "呕吐、便秘、腹胀、黑便，误吸可致吸入性肺炎与呼吸衰竭。",
      "monitoring": "监测气道保护、呼吸状态、肠鸣音与排便，评估毒物血药浓度与器官功能，必要时复查影像排除误吸。",
      "age_limit": "婴儿与新生儿使用需评估气道保护能力与误吸风险，通常需在具备气道管理条件时给药。",
      "interactions": "可吸附并降低口服解毒剂与其他口服药物吸收，需按中毒处理规范错开给药时间。",
