      "generic_name": "丙戊酸钠",
      "aliases": [
        "丙戊酸",
        "丙戊酸钠口服溶液"
      ],
      "category": "抗癫痫与神经用药",
      "drug_class": "广谱抗癫痫药（脂肪酸衍生物）",
      "forms": [
        "口服溶液 200mg/5ml",
        "口服片 0.2g",
        "口服片 0.5g",
        "注射用 0.4g"
      ],
      "indications": "教学范围内用于全面性发作、失神发作、肌阵挛发作与局灶性发作的抗癫痫治疗讨论。",
      "peds_notes": "儿童广谱抗癫痫药，按体重给药并逐步加量；3 岁以下、多药联用、线粒体病或发育迟缓者肝毒性风险较高，需重点评估；血药浓度须结合发作控制与不良反应解读，不单独依赖数值。",
      "dose_note": "教学性起始范围约 10–15 mg/kg/日，分 1–2 次，按耐受性每 3–7 天递增，维持量常用约 15–40 mg/kg/日；具体剂量、递增速度与血药浓度目标须核对本院制剂说明书与癫痫诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次不超过说明书标注上限，日总量一般不超过 60 mg/kg，超过时须有血药浓度与肝功能监测支持。",
      "renal_note": "肾功能不全时游离药物浓度可能升高，需结合血药浓度与临床反应调整。",
      "hepatic_note": "肝功能不全或疑似尿素循环障碍者风险显著升高，用药前查肝功能，出现反复呕吐、嗜睡或黄疸须立即停药评估。",
      "cautions": "需警惕高氨血症性脑病；青春期与育龄期用药须讨论生殖风险；不可骤停以免诱发发作加重。",
      "contraindications": "肝功能不全或严重肝炎病史、尿素循环障碍、对本品过敏者禁用；已知线粒体病相关基因突变者禁用。",
      "adverse": "体重增加、震颤、脱发、恶心、血小板减少、高氨血症、肝损伤、胰腺炎。",
      "monitoring": "用药前及用药中监测肝功能、血常规、血氨与血药浓度；记录发作频率、体重与行为情绪变化。",
      "age_limit": "2 岁以下婴幼儿肝毒性风险较高，须严格评估获益与风险；3 岁以下单药使用亦需密切监测肝功能。",
      "interactions": "与拉莫三嗪合用须大幅减少拉莫三嗪剂量以免严重皮疹；与水杨酸类合用增加游离药物浓度；与碳青霉烯类合用可使血药浓度骤降。",
