      "dose_note": "教学性起始范围约 8–10 mg/kg/日分 2 次，按耐受每 3–7 天递增，维持量约 20–30 mg/kg/日，必要时可至约 45 mg/kg/日；具体剂量与递增方案须核对本院制剂说明书与癫痫诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次不超过说明书上限，日总量一般不超过 45 mg/kg，超过时需血钠与血药浓度监测。",
      "renal_note": "肌酐清除率低于 30 ml/min 时起始剂量减半并缓慢加量。",
