      "peds_notes": "儿童起始剂量与加量节奏直接决定皮疹风险；合用丙戊酸时须大幅减量并延长加量间隔；出现皮疹即停药评估，警惕重症药疹。",
      "dose_note": "教学性方案：单药约 0.3–0.6 mg/kg/日起始并按周递增；合用酶诱导剂时起始约 0.6 mg/kg/日；维持量随合并用药变化，常见约 1–15 mg/kg/日；具体起始量、递增节奏与维持量须核对本院制剂说明书与癫痫诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次与日总量按合并用药分层设定，不得超过说明书对应上限，加量间隔一般不少于 1–2 周。",
      "renal_note": "肾功能不全者需减量，血液透析后可考虑补充剂量。",
      "hepatic_note": "中重度肝功能不全者起始与维持量均需减量，肝功能受损越重减量越明显。",
      "cautions": "皮疹为最需关注的信号，伴发热或黏膜受累须立即停药就医；合用丙戊酸时血药浓度显著升高；不可骤停。",
      "contraindications": "对本品过敏者禁用；既往使用后出现严重皮疹者不再使用。",
      "adverse": "皮疹、头痛、嗜睡、失眠、复视、血细胞减少、肝功能异常。",
