      "age_limit": "2 岁以下儿童数据有限；婴幼儿发热伴皮疹时须与药疹鉴别。",
      "interactions": "丙戊酸显著抑制其代谢升高浓度；卡马西平、苯妥英、苯巴比妥加速代谢降低浓度；含雌激素避孕药可降低其浓度。",
