      "peds_notes": "儿童按体重给药，低剂量起始缓慢加量以减少认知与行为不良反应；注意少汗与体温调节障碍，夏季与发热时须补水；代谢性酸中毒与肾结石风险需随访。",
      "dose_note": "教学性起始约 1–3 mg/kg/日（常自 1 mg/kg/日起），每周递增约 1–3 mg/kg，维持量约 5–9 mg/kg/日分两次；具体起始量、递增与维持须核对本院制剂说明书与癫痫诊疗规范，不能照抄为处方。",
