      "peds_notes": "儿童按体重或体表面积计算；静脉给药须充分水化以减少肾小管结晶；疱疹性脑炎与新生儿感染需静脉治疗并密切评估肾功能；口服生物利用度低，重症不使用口服途径。",
      "dose_note": "教学性范围：口服约 20 mg/kg/次（或按体表面积 750 mg/m2）每日 4 次；静脉约 5–10 mg/kg/次每 8 小时一次，疗程 7–14 天；具体剂量、间隔与疗程须核对本院制剂说明书与感染诊疗规范，不能照抄为处方。",
      "max_single": "原则性参考：单次与日总量按说明书上限控制，儿童按体表面积折算不得超过对应上限。",
      "renal_note": "肾功能不全者必须按肌酐清除率延长间隔或减量；静脉给药前后充分补液并监测尿量。",
      "hepatic_note": "轻中度肝功能不全一般无需调整，重度需谨慎并监测。",
      "cautions": "静脉外渗可致组织损伤；快速推注可致肾功能损害；与肾毒性药物合用需谨慎。",
