      "peds_notes": "儿童按体重计算，川崎病强调发病 10 天内单次大剂量；输注速度须逐步递增并监测输注反应；含麦芽糖或蔗糖辅料的产品在肾功能不全与糖代谢异常患儿需评估；属血液制品，使用前按规范完成知情与批签发核对。",
