      "max_single": "原则性参考：单次不超过 2 g/kg，更大剂量可致容量负荷与高黏滞血症，须分次或延长输注。",
      "renal_note": "含蔗糖辅料制剂在肾功能不全者可致渗透性肾损害，须核对辅料并监测肾功能与尿量。",
